def main_of(display):
    """العقد الرئيسي (أحد العقود الخمسة أو الإدارة) من اسم مركز التقرير."""
    d = _nm(display)
    if not d:
        return None
    if "الادارهالعامه" in d or d.startswith("الاداره"):
        return "الإدارة"
    for kws, name in ((("الرياض",), "العقد الموحد بالرياض"), (("مكه", "خليص"), "العقد الموحد بمكة"),
                      (("الباحه", "المخواه", "القنفده"), "العقد الموحد بالباحة"),
                      (("عسير", "ابها", "المجارده", "محايل"), "العقد الموحد بعسير"),
                      (("تبوك", "الوجه", "الوجة", "املج", "المج", "ضبا", "حقل"), "العقد الموحد بتبوك")):
        if any(k in d for k in kws):
            return name
    return None


def cc_resolve(text, ccpairs, cache):
    """يعيد (اسم مركز التقرير أو "", العقد الرئيسي أو None) من نص مركز التكلفة المخزَّن (قد يكون مقطوعاً من آخره)."""
    if text in cache:
        return cache[text]
    t = _nm(text)
    best, bk = "", 0
    for key, disp in ccpairs:
        if not key:
            continue
        if key in t:
            k = len(key)
        else:
            k = 0
            for n in range(min(len(key), len(t)), 8, -1):
                if t.endswith(key[:n]):
                    k = n
                    break
        if k > bk:
            best, bk = disp, k
    main = main_of(best) if best else None
    cache[text] = (best, main)
    return best, main


