def _num(v):
    try:
        v = float(v)
        return 0.0 if np.isnan(v) else v
    except Exception:
        return 0.0


# ---------------- قراءة التقرير ----------------
def _open_xlsx(raw):
    import openpyxl, zipfile
    try:
        return openpyxl.load_workbook(io.BytesIO(raw), data_only=True, read_only=False)
    except Exception:
        zin = zipfile.ZipFile(io.BytesIO(raw))
        out = io.BytesIO()
        with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
            for it in zin.infolist():
                d = zin.read(it.filename)
                if it.filename.startswith("xl/") and it.filename.endswith(".xml"):
                    s = d.decode("utf-8", "ignore")
                    s = re.sub(r"<bookViews>.*?</bookViews>|<(?:\w+:)?pageSetup\b[^>]*?/?>(?:</(?:\w+:)?pageSetup>)?|<headerFooter>.*?</headerFooter>", "", s, flags=re.S)
                    d = s.encode("utf-8")
                z.writestr(it, d)
        out.seek(0)
        return openpyxl.load_workbook(out, data_only=True)


