REF_COLS = ["النوع", "التاريخ", "المبلغ", "الجهة", "البيان"]


def parse_customers(raw):
    """تقرير العملاء (ورقة تفصيلي): سطور القبض."""
    wb = _open_xlsx(raw)
    ws = wb["تفصيلي"] if "تفصيلي" in wb.sheetnames else wb.worksheets[-1]
    out = []
    for r in ws.iter_rows(values_only=True):
        r = list(r) + [None] * 9
        if r[6] == "قبض" and isinstance(r[5], (dt.datetime, dt.date)):
            out.append(["عميل", pd.Timestamp(r[5]).strftime("%Y-%m-%d"), round(_num(r[1]), 2), str(r[4] or ""), str(r[3] or "")])
        elif r[6] == "فاتورة" and r[7] is not None:
            out.append(["فاتورة", pd.Timestamp(r[5]).strftime("%Y-%m-%d") if isinstance(r[5], (dt.datetime, dt.date)) else "", round(_num(r[2]), 2), str(r[4] or ""), str(r[7])])
    return pd.DataFrame(out, columns=REF_COLS)


def parse_vendors(raw):
    """تقرير الموردين (حركة الموردين): سطور المدفوعات."""
    wb = _open_xlsx(raw)
    ws = wb.active
    out = []
    for r in ws.iter_rows(values_only=True):
        d = next((x for x in r if isinstance(x, (dt.datetime, dt.date))), None)
        if d is None:
            continue
        strs = [x for x in r if isinstance(x, str)]
        if len(strs) >= 3 and strs[2] == "مدفوعات":
            out.append(["مورد", pd.Timestamp(d).strftime("%Y-%m-%d"), round(_num(r[2]), 2), strs[1], strs[0]])
    return pd.DataFrame(out, columns=REF_COLS)


def _nm(x):
    x = str(x or "")
    for a, b in (("أ", "ا"), ("إ", "ا"), ("آ", "ا"), ("ة", "ه"), ("ى", "ي")):
        x = x.replace(a, b)
    return re.sub(r"[\s\-_/\\()\.]+", "", x)


def parse_activities(raw):
    """ملف أنشطة الموردين: اسم المورد (أول نص) ونشاطه (آخر نص)."""
    ws = _open_xlsx(raw).active
    out = []
    for r in list(ws.iter_rows(values_only=True))[1:]:
        s_ = [str(x).strip() for x in r if isinstance(x, str) and x.strip()]
        if len(s_) >= 2:
            out.append(["نشاط", "", 0.0, s_[0], s_[-1]])
    return pd.DataFrame(out, columns=REF_COLS)


def detect_ref(raw):
    wb = _open_xlsx(raw)
    if "تفصيلي" in wb.sheetnames:
        return "عميل"
    ws0 = wb.active
    for rw in list(ws0.iter_rows(min_row=1, max_row=4, values_only=True)):
        if any(str(x or "").strip() == "تاريخ الشراء" for x in rw):
            return "أصل"
    hdr = [str(c.value or "") for c in ws0[1]]
    return "نشاط" if any("الاعمال" in h for h in hdr) else "مورد"


def _act_lookup(actmap, vendor):
    if not vendor or not actmap:
        return ""
    k = _nm(vendor)
    if k in actmap:
        return actmap[k]
    for kk, v in actmap.items():
        if len(kk) >= 8 and len(k) >= 8 and (kk.startswith(k[:12]) or k.startswith(kk[:12])):
            return v
    return ""


