# ---------------- التصنيف ----------------
def classify(lines, acct_rules, desc_rules, vend_rules=None, vmaps=None, act_rules=None, actmap=None):
    items = []
    vends = []
    acts = []
    for _, r in lines.iterrows():
        code, name, desc = str(r["كود الحساب"]), str(r["الحساب المقابل"]), str(r["البيان"])
        item = None
        for fld, pat, tgt in acct_rules:
            pat = str(pat)
            hit = (fld == "كود" and code.startswith(pat)) or (fld == "اسم" and pat in name) or (fld == "بيان" and pat in desc)
            if hit:
                item = tgt
                break
        vend = ""
        if vmaps is not None and r["الأثر النقدي"] < 0:
            vend = _lookup(vmaps, str(r["التاريخ"]), r["الأثر النقدي"])
        vends.append(vend)
        act = _act_lookup(actmap, vend)
        acts.append(act)
        if item == "@بيان":
            item = None
            if act:
                for pat, tgt in (act_rules or []):
                    if str(pat) in act:
                        item = tgt
                        break
            if item is not None:
                items.append(item)
                continue
            for pat, tgt in desc_rules:
                if str(pat) in desc:
                    item = tgt
                    break
            if item is None and vend:
                for pat, tgt in (vend_rules or []):
                    if str(pat) in vend:
                        item = tgt
                        break
            if item is None:
                item = UNCLASS_OUT if r["الأثر النقدي"] < 0 else UNCLASS_IN
        if item is None:
            item = UNCLASS_OUT if r["الأثر النقدي"] < 0 else UNCLASS_IN
        if item == "تحصيلات من العملاء" and r["الأثر النقدي"] < 0:
            item = "غرامات ومدفوعات لعملاء"
        # الحسابات التي تُصنَّف حسب الإشارة
        if item == "سداد التمويل والمرابحات" and r["الأثر النقدي"] > 0:
            item = "متحصلات التمويل والمرابحات"
        if item == "شراء أصول وسيارات ومعدات" and r["الأثر النقدي"] > 0:
            item = "متحصلات بيع أصول وسيارات"
        items.append(item)
    out = lines.copy()
    out["البند"] = items
    out["المورد"] = vends
    out["النشاط"] = acts
    out["المجموعة"] = out["البند"].map(lambda i: ITEM_GROUP.get(i, "ت-خارج"))
    return out


